import json
from collections import Counter
for t in ['task_000578_cebe85a5','task_001321_658ce4a8','task_000958_4bb2b05d','task_001031_a8f0eb37','task_001653_c4cafa73']:
  m=json.load(open(t+'.messages.json'))
  # extract tool call inputs from assistant tool_calls
  calls=[]
  for msg in m:
    if msg.get('role')=='assistant':
      tcs=msg.get('tool_calls') or []
      for tc in tcs:
        fn=tc.get('function',{})
        calls.append(json.dumps([fn.get('name'),fn.get('arguments')]))
  cnt=Counter(calls)
  if calls:
    top,n=cnt.most_common(1)[0]
    # find max consecutive run
    maxrun=cur=1
    for i in range(1,len(calls)):
      if calls[i]==calls[i-1]: cur+=1; maxrun=max(maxrun,cur)
      else: cur=1
    print(t,'calls',len(calls),'maxIdentical',n,'maxConsecRun',maxrun,'::',top[:90])
  else:
    print(t,'no tool_calls in messages format')
"

